  const hasX = (t) => /(^|[^\p{L}_])x(?![\p{L}\p{Nd}_])/u.test(t);
  const hasVar = (t, v) => new RegExp('(^|[^\\p{L}_\\\\])' + v + '(?![\\p{L}\\p{Nd}_])', 'u').test(t);
  const r6 = (v) => engineNum(+(+v).toPrecision(6));
