    variable: tr('variable', '変数'),
    expr: tr('expression', '式'),
    order: tr('order', '階数'),
    lower: tr('lower limit', '下端'),
    upper: tr('upper limit', '上端'),
    approach: tr('value approached', '近づける値'),
    direction: tr('direction', '向き'),
    equation: tr('equation', '方程式'),
