    vector2: tr('vector 2', 'ベクトル 2'),
    data: tr('data', 'データ'),
    mean: tr('mean μ', '平均 μ'),
    sd: tr('standard deviation σ', '標準偏差 σ'),
    cumulative: tr('cumulative (1)', '累積（1）'),
    prob: tr('probability P', '確率 P'),
    successes: tr('successes k', '成功の回数 k'),
    trials: tr('trials n', '試行の回数 n'),
