      if (lines.indexOf(expr) >= 0) return;
      if (lines.length >= 6) { toast(tr('Up to 6 functions', '関数は 6 つまでです'), 1800); return; }
      P.ta.value = lines.concat(toDisplay(expr)).join('\n');
      P.keep = true;
