    if (!y0 || !m || /diff\(|where/.test(y0 + m)) { toast(tr('Could not find the tangent there', 'その点の接線を求められませんでした'), 2200); return ''; }
    const line = `(${m}) × (x − (${a})) + (${y0})`;
