    showResult(U.out, tr('Area ', '面積 ') + U.areaText);
    if (real) U.out.append(el('div', { class: 'form-hint', text: realNote(!!g, real.parts) }));
    P.areaExpr = expr;
    U.areaKey = key;
    showAreaMode();
