          if (M.kind === 'h') { g.moveTo(sx(x), sy(2 * M.v - y1)); g.lineTo(sx(x), sy(2 * M.v - y2)); }
          else { g.moveTo(sx(2 * M.v - x), sy(y1)); g.lineTo(sx(2 * M.v - x), sy(y2)); }
