        const zs = [];
        for (const q of here) { const m = sides.indexOf(q.s), fv = vals[2 * m], gv = vals[2 * m + 1]; if (isFinite(fv) && isFinite(gv)) zs.push(top ? Math.max(fv, gv) : Math.min(fv, gv)); }
