      if (!v) { vrow.val.textContent = tr('could not be calculated', '計算できませんでした'); R.msg.textContent = ''; return; }
      if (v.inf) { vrow.val.textContent = tr('infinite', '無限大'); R.msg.textContent = ''; return; }
