          chartCap.textContent = trf('{0} bins of width {1} (from {2})', '幅 {1} の階級が {0} 個（{2} から）', nb, statNum(w, 6), statNum(start, 8)) + (D.bw ? '' : tr(' — automatic', '（自動）'));
